INSERT INTO public.courses (id,name,description,lat,lng,path,tags,diff,distance,author,status) VALUES
('pet_20261012_haeundae','부산 해운댕길','부산시가 반려동물 공감 산책로로 지정한 해운대 시외버스터미널~엘시티 구간입니다. 공식 안내 거리 1.4km. 사진은 인근 장소의 경관 참고사진이며 지정 산책로 전체 사진이 아닙니다. 전체 경로 좌표와 계단·경사·쉼터 정보는 미확인입니다. 지도 핀은 대표 위치이며 출발점으로 확인한 좌표가 아닙니다. 허용 구간 밖의 해변·시설 출입과 개별 이용수칙은 현장 안내를 확인하세요. · 공식안내: https://www.busan.go.kr/park/pet02 확인일: 2026-10-12',35.1606694,129.1686886,NULL,ARRAY['부산','공식안내','동반구간확인','경로미확인']::text[],'미확인','1.4km','부산광역시 자료 확인','pending'),
